    fatigueAmeli2026:['Ameli : fatigue, observations utiles et situations nécessitant une consultation','https://www.ameli.fr/assure/sante/themes/asthenie-fatigue/bons-reflexes-cas-faut-consulter'],
    anxiety2026:['NIAAA : alcool et troubles psychiques associés (en anglais)','https://www.niaaa.nih.gov/health-professionals-communities/core-resource-on-alcohol/mental-health-issues-alcohol-use-disorder-and-common-co-occurring-conditions'],
    hangover2026:['NIAAA : comprendre la gueule de bois et ses limites (en anglais)','https://www.niaaa.nih.gov/publications/brochures-and-fact-sheets/hangovers'],
    hangoverHse2026:['HSE : symptômes, causes et limites des remèdes contre la gueule de bois (en anglais)','https://www2.hse.ie/living-well/alcohol/health/how-alcohol-can-affect-everyday-life/hangover/'],
    shynessStudy2026:['Marsh et coll. : étude naturaliste sur timidité, alcool et anxiété, manuscrit UCL (en anglais)','https://discovery.ucl.ac.uk/10065051/3/Lawn_Final_Manuscript_forWL.pdf'],
    calories2026:['NHS : calories apportées par l’alcool (en anglais)','https://www.nhs.uk/live-well/alcohol-advice/calories-in-alcohol/'],
    beerLaw2026:['Légifrance : décret 92-307, article 1, dénominations des bières','https://www.legifrance.gouv.fr/loda/article_lc/LEGIARTI000033406892/'],
    beerLabel2026:['DGCCRF : comprendre l’étiquetage des bières','https://www.economie.gouv.fr/dgccrf/les-fiches-pratiques/tout-savoir-sur-letiquetage-des-bieres'],
    substitute2026:['Alcool Info Service : réponse professionnelle sur les boissons de substitution','https://www.alcool-info-service.fr/questions-reponses/boisson-de-substitution'],
    cooking2026:['USDA : Table of Nutrient Retention Factors, Release 6, décembre 2007 (PDF en anglais)','https://www.ars.usda.gov/ARSUserFiles/80400530/pdf/retn06.pdf'],
    drivingLaw2026:['Service Public : alcool au volant, règles vérifiées le 27 août 2026','https://www.service-public.gouv.fr/particuliers/vosdroits/F2881'],
